"""Fail CI when a requirements-*.lock is stale relative to uv.lock.

Why this check exists (F-12b408df): requirements-dev.lock and
requirements-build.lock are what CI actually installs from, but they are
*exports* of uv.lock, regenerated by hand. Nothing enforced that the export was
re-run after uv.lock changed, so a dependency bump in uv.lock (now happening on
a schedule, via the Dependabot `uv` entry) would silently leave the install
files behind: CI stays green because it installs the stale lock, and the new
version never reaches the gate.

The check is deliberately mechanical: each requirements-*.lock's header comment
records the exact `uv export` command that produced it (see the file headers,
which the regeneration workflow now treats as normative). This script parses
that command, re-runs it against uv.lock into a temp file, and diffs. If the
committed file digressed from what uv.lock currently exports, the diff is
non-empty and CI fails.

Dependabot runs concurrently with this: it edits uv.lock on its own branch, and
this check makes the *paired* requirement-export edit mandatory on the same PR
-- a dependabot PR that only touches uv.lock turns red, which is exactly the
point (otherwise the counterfeited green described above happens on every
Dependabot run).

Usage:
    python scripts/check_lock_consistency.py [--root .]

Exit 0 when every requirements-*.lock matches its regenerated export, 1 on any
mismatch, 2 on unreadable input or missing uv.
"""

from __future__ import annotations

import argparse
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

# Header of each requirements-*.lock contains the export command on the line
# right after the autogenerated marker, e.g.:
#   #    uv export --frozen --no-emit-project --format requirements.txt \
#   #        --extra dev --extra messaging --extra bedrock -o requirements-dev.lock
_EXPORT_MARKER = "uv export"
_HEADER_COMMENT_PREFIX = "#"


def export_command_from_header(path: Path) -> list[str] | None:
    """Return the argv for regenerating `path` from uv.lock, or None."""
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:  # pragma: no cover - trivial wrapper
        raise SystemExit(f"cannot read {path}: {exc}") from exc
    for raw in lines:
        if not raw.startswith(_HEADER_COMMENT_PREFIX):
            break  # header comment block ends at the first non-comment line
        stripped = raw.lstrip(_HEADER_COMMENT_PREFIX).strip()
        if not stripped.startswith(_EXPORT_MARKER):
            continue
        # Rebuild the command without the shell-line-continuation backslashes.
        argv = [tok for tok in stripped.split() if tok != "\\"]
        return argv
    return None


_HASH_LINE_RE = re.compile(r"--hash=(\S+)")
_ENTRY_START_RE = re.compile(r"^([A-Za-z0-9_.\-\[\]]+==[^\s;]+)\s*(?:;\s*(.*?))?\s*\\?$")


def normalize_lock(text: str) -> dict[tuple[str, str, str], frozenset[str]]:
    """Parse a requirements-*.lock into {(name==version, marker): hashes}.

    uv export may emit the same set of hashes in a different row order across
    runs (observed: identical 3254-hash set, different ordering), so comparison
    is done on the *set* per distribution, never on raw bytes.
    """
    result: dict[tuple[str, str, str], frozenset[str]] = {}
    current: tuple[str, str, str] | None = None
    hashes: set[str] = set()

    def flush() -> None:
        nonlocal current, hashes
        if current is not None:
            result[current] = frozenset(hashes)
        current = None
        hashes = set()

    for raw in text.splitlines():
        # Header comment block (column-0 '#' lines) and per-entry '  # via X'
        # notes are not part of a distribution spec.
        if raw.lstrip().startswith("#") and not raw.startswith((" ", "\t")):
            flush()
            continue
        if raw.strip().startswith("#"):
            continue  # indented "# via ..." inside an entry
        stripped = raw.strip()
        if not stripped:
            flush()
            continue
        m = _ENTRY_START_RE.match(stripped)
        if m and not stripped.startswith(("--hash=", "--index")):
            flush()
            current = (m.group(1), m.group(2) or "", "")
            continue
        hm = _HASH_LINE_RE.search(raw)
        if hm and current is not None:
            hashes.add(hm.group(1))
    flush()
    return result


def regenerated_matches(path: Path, argv: list[str]) -> bool:
    """Run the export command (with output redirected to a temp file) and diff."""
    # Fresh directory (not mkstemp): uv creates the -o target itself and would
    # hit an access error trying to atomically replace an existing file.
    tempdir = tempfile.mkdtemp(prefix="uv-export-check-")
    out_path = Path(tempdir) / "export.lock"
    try:
        # Replace the -o target with our temp file so we never clobber the
        # committed lock, then run uv export from the repo root.
        if "-o" in argv:
            oi = argv.index("-o")
            argv = argv[:oi] + ["-o", str(out_path)] + argv[oi + 2 :]
        else:  # pragma: no cover - defensive; the recorded commands always have -o
            argv = argv + ["-o", str(out_path)]
        proc = subprocess.run(
            argv,
            cwd=path.parent,
            capture_output=True,
            text=True,
            encoding="utf-8",
        )
        if not out_path.exists() and proc.returncode == 0:
            print("  uv export produced no output file", file=sys.stderr)
            return False
        if proc.returncode != 0:
            print(f"  uv export failed ({proc.returncode}): {proc.stderr.strip()}",
                  file=sys.stderr)
            return False
        committed = path.read_text(encoding="utf-8")
        regenerated = out_path.read_text(encoding="utf-8")
        # Hash row order is not stable across uv runs; compare normalized maps.
        return normalize_lock(committed) == normalize_lock(regenerated)
    finally:
        shutil.rmtree(tempdir, ignore_errors=True)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--root", default=".", help="repository root")
    args = parser.parse_args(argv)

    if shutil.which("uv") is None:
        print("uv not found on PATH -- cannot verify export consistency",
              file=sys.stderr)
        return 2

    root = Path(args.root).resolve()
    mismatched: list[str] = []
    missing_cmd: list[str] = []
    for lock in sorted(root.glob("requirements-*.lock")):
        cmd = export_command_from_header(lock)
        if cmd is None:
            missing_cmd.append(lock.name)
            continue
        print(f"checking {lock.name}: {' '.join(cmd)}")
        if not regenerated_matches(lock, cmd):
            mismatched.append(lock.name)

    for name in missing_cmd:
        print(f"{name}: no 'uv export' command in header -- cannot verify", file=sys.stderr)
    for name in mismatched:
        print(f"{name}: committed lock differs from `uv export` of uv.lock -- "
              "re-run the export and commit both", file=sys.stderr)
    if mismatched or missing_cmd:
        print(f"{len(mismatched)} stale, {len(missing_cmd)} unverifiable", file=sys.stderr)
        return 1
    print("all requirements-*.lock are consistent with uv.lock")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
